def is_hollow(shape_cells):
    """Check if a shape encloses empty space (has a hole)"""
    if len(shape_cells) < 4:
        return False

    rows = sorted([r for r,c in shape_cells])
    cols = sorted([c for r,c in shape_cells])
    min_r, max_r = rows[0], rows[-1]
    min_c, max_c = cols[0], cols[-1]

    for r in range(min_r + 1, max_r):
        for c in range(min_c + 1, max_c):
            if (r, c) not in shape_cells:
                return True
    return False

